while($l = fgets(STDIN)) {
    echo preg_replace_callback('/(\b\d?\d+)\b/', function ($m) {
        $n = $m[1];

        while($n >= 1) {
            $d[] = [
                '〇',
                '一',
                '二',
                '三',
                '四',
                '五',
                '六',
                '七',
                '八',
                '九',
            ][$n % 10];
            $n = $n / 10;
        }

        return implode(array_reverse($d));
    }, $l);
}

while($l = fgets(STDIN)) {
    echo preg_replace_callback('/(?P<num>\b[1-9]?[0-9]+)\b/', fn ($m) => k($m['num']), $l);
}

function k($n)
{
    $j= ["〇","一","二","三","四","五","六","七","八","九"];

    do {
        $d[] = $j[$n%10];
        $n = $n / 10;
    } while($n >= 1);

    return implode(array_reverse($d));
}
